    var rowsNow=document.getElementById('shop').children;
    var rw=rowsNow[P._shopSel]; if(!rw) break;
    var bb=rw.querySelector('button');
    if(!bb||bb.disabled) break;
    bb.click(); _got++;
  }
} finally { SHOP_TALLY=null; }
